45	  using LIST_GRAPH = std::vector<GRAPH>;
46	  using LIST_BYTES = std::vector<BYTES>;
47	  using LIST_NAMED_ATTRS = std::vector<NAMED_ATTRS>;
48	  using LIST_DATA_TYPE = std::vector<DATA_TYPE>;
49	  using LIST_LIST_INT = std::vector<std::vector<int64_t>>;
50	  using LIST_LIST_FLOAT = std::vector<std::vector<float>>;
51	  using NamedAttrs = ge::NamedAttrs;
52	  // public type definitions
53	  // 这堆ValueType的预定义本质上是反向依赖，AnyValue不应该反向依赖ComputeGraph等数据结构
54	  // 后续整改掉
55	  enum ValueType {
56	    VT_NONE = 0,
57	    VT_STRING = 1,
58	    VT_FLOAT = 2,
59	    VT_BOOL = 3,
60	    VT_INT = 4,
61	    VT_TENSOR_DESC = 5,
62	    VT_TENSOR = 6,
63	    VT_BYTES = 7,
64	    VT_GRAPH = 8,
65	    VT_NAMED_ATTRS = 9,
66	    VT_LIST_LIST_INT = 10,
67	    VT_DATA_TYPE = 11,
68	    VT_LIST_LIST_FLOAT = 12,
69	
70	    VT_LIST_BASE = 1000,
71	    VT_LIST_STRING = static_cast<int32_t>(VT_LIST_BASE) + static_cast<int32_t>(VT_STRING),
72	    VT_LIST_FLOAT = static_cast<int32_t>(VT_LIST_BASE) + static_cast<int32_t>(VT_FLOAT),
73	    VT_LIST_BOOL = static_cast<int32_t>(VT_LIST_BASE) + static_cast<int32_t>(VT_BOOL),
74	    VT_LIST_INT = static_cast<int32_t>(VT_LIST_BASE) + static_cast<int32_t>(VT_INT),
75	    VT_LIST_TENSOR_DESC = static_cast<int32_t>(VT_LIST_BASE) + static_cast<int32_t>(VT_TENSOR_DESC),
76	    VT_LIST_TENSOR = static_cast<int32_t>(VT_LIST_BASE) + static_cast<int32_t>(VT_TENSOR),
77	    VT_LIST_BYTES = static_cast<int32_t>(VT_LIST_BASE) + static_cast<int32_t>(VT_BYTES),
78	    VT_LIST_GRAPH = static_cast<int32_t>(VT_LIST_BASE) + static_cast<int32_t>(VT_GRAPH),
79	    VT_LIST_NAMED_ATTRS = static_cast<int32_t>(VT_LIST_BASE) + static_cast<int32_t>(VT_NAMED_ATTRS),
80	    VT_LIST_DATA_TYPE = static_cast<int32_t>(VT_LIST_BASE) + static_cast<int32_t>(VT_DATA_TYPE),
81	  };
