113	    InnerSet(std::forward<T>(value));
114	    return GRAPH_SUCCESS;
115	  }
116	
117	  // 如果只有万能引用，那么Set<int>(左值)这种调用方法会出错，因此有了这个函数
118	  template <typename T>
119	  graphStatus SetValue(const T &value) {
120	    Clear();
121	    InnerSet(value);
122	    return GRAPH_SUCCESS;
123	  }
124	
125	  template <typename T>
126	  graphStatus SetValue(std::initializer_list<T> values) {
127	    Clear();
128	    InnerSet(std::vector<T>(std::move(values)));
