142	  template <class T>
143	  const T *Get() const {
144	    if (!SameType<T>()) {
145	      return nullptr;
146	    }
147	    if (IsEmpty()) {
148	      return nullptr;
149	    }
150	    return PtrToPtr<const void, const T>(GetAddr());
151	  }
152	  template <class T>
153	  T *MutableGet();
154	
155	  template <class T>
156	  bool SameType() const noexcept {
157	    if (operate_ == nullptr) {
158	      return false;
159	    }
160	    TypeId tid = kInvalidTypeId;
161	    operate_(OperateType::kGetTypeId, this, &tid);
162	    return tid == GetTypeId<T>();
163	  }
164	
165	  void Swap(AnyValue &other) noexcept;
166	
