182	 private:
183	  template <typename T>
184	  void InnerSet(T &&value) {
185	    using PureT = typename std::remove_cv<typename std::remove_reference<T>::type>::type;
186	    using Inline = std::integral_constant<bool, sizeof(PureT) <= sizeof(holder_)>;
187	    using Operations = typename std::conditional<Inline{}, AnyValue::InlineOperations<PureT>,
188	                                                 AnyValue::AllocateOperations<PureT>>::type;
189	
190	    Operations::Construct(std::forward<T>(value), this);
191	  }
192	  const void *GetAddr() const;
193	
194	  enum class OperateType : uint32_t { kOpClear, kOpGetAddr, kOpClone, kOpMove, kGetTypeId, kOperateTypeEnd };
195	
196	  template <typename T>
197	  class InlineOperations {
198	   public:
199	    static void Operate(const OperateType ot, const AnyValue *const av, void *const out);
200	    static void Construct(const T &value, AnyValue *const av);
201	    static void Construct(T &&value, AnyValue *const av);
202	  };
203	
204	  template <typename T>
205	  class AllocateOperations {
206	   public:
207	    static void Operate(const OperateType ot, const AnyValue *const av, void *const out);
208	    static void Construct(const T &value, AnyValue *const av);
209	    static void Construct(T &&value, AnyValue *const av);
210	  };
211	
212	  using ValueBuf = std::aligned_storage<sizeof(void *)>::type;
213	  using ValueHolder = union {
214	    void *pointer;
215	    std::aligned_storage<sizeof(void *)>::type inline_buf;
216	  };
217	  ValueHolder holder_ = {nullptr};
218	
219	  void (*operate_)(OperateType ot, const AnyValue *av, void *out){nullptr};
220	};
221	using GeAttrValue = AnyValue;
222	
223	template <typename T>
224	void AnyValue::AllocateOperations<T>::Construct(const T &value, AnyValue *const av) {
225	  av->holder_.pointer = new (std::nothrow) T(value);
226	  av->operate_ = AnyValue::AllocateOperations<T>::Operate;
227	}
228	template <typename T>
229	void AnyValue::AllocateOperations<T>::Construct(T &&value, AnyValue *const av) {
230	  av->holder_.pointer = ::new (std::nothrow) T(std::forward<T>(value));
231	  av->operate_ = AnyValue::AllocateOperations<T>::Operate;
232	}
233	template <typename T>
234	void AnyValue::AllocateOperations<T>::Operate(const AnyValue::OperateType ot, const AnyValue *const av,
235	                                              void *const out) {
236	  switch (ot) {
237	    case OperateType::kOpClear: {
238	      auto *const av_p = PtrToPtr<void, AnyValue>(out);
239	      delete PtrToPtr<void, T>(av_p->holder_.pointer);
240	      av_p->holder_.pointer = nullptr;
241	      av_p->operate_ = nullptr;
242	      break;
243	    }
244	    case OperateType::kOpGetAddr:
245	      *PtrToPtr<void, void *>(out) = const_cast<void *>(av->holder_.pointer);
246	      break;
247	    case OperateType::kOpClone:
248	      PtrToPtr<void, AnyValue>(out)->holder_.pointer =
249	          new (std::nothrow) T(*PtrToPtr<const void, const T>(av->holder_.pointer));
250	      PtrToPtr<void, AnyValue>(out)->operate_ = av->operate_;
251	      break;
252	    case OperateType::kOpMove: {
253	      auto *const av_p = PtrToPtr<void, AnyValue>(out);
254	      av_p->holder_.pointer = av->holder_.pointer;
255	      av_p->operate_ = av->operate_;
256	      const_cast<AnyValue *>(av)->holder_.pointer = nullptr;
257	      break;
258	    }
259	    case OperateType::kGetTypeId:
260	      *PtrToPtr<void, TypeId>(out) = GetTypeId<T>();
261	      break;
262	    default:
263	      break;
264	  }
265	}
266	template <typename T>
267	void AnyValue::InlineOperations<T>::Construct(const T &value, AnyValue *const av) {
268	  (void)::new (&(av->holder_.inline_buf)) T(value);
269	  av->operate_ = AnyValue::InlineOperations<T>::Operate;
270	}
271	template <typename T>
272	void AnyValue::InlineOperations<T>::Construct(T &&value, AnyValue *const av) {
273	  Construct(value, av);
274	}
275	template <typename T>
276	void AnyValue::InlineOperations<T>::Operate(const AnyValue::OperateType ot, const AnyValue *const av, void *const out) {
277	  switch (ot) {
278	    case OperateType::kOpClear: {
279	      auto *const av_p = PtrToPtr<void, AnyValue>(out);
280	      PtrToPtr<std::aligned_storage<sizeof(void *)>::type, T>(&av_p->holder_.inline_buf)->~T();
281	      av_p->operate_ = nullptr;
282	      break;
283	    }
284	    case OperateType::kOpGetAddr:
285	      *PtrToPtr<void, void *>(out) = const_cast<void *>(PtrToPtr<const ValueBuf, const void>(&av->holder_.inline_buf));
286	      break;
287	    case OperateType::kOpClone: {
288	      auto *const av_p = PtrToPtr<void, AnyValue>(out);
289	      (void)new (&av_p->holder_.inline_buf)
290	          T(*PtrToPtr<const std::aligned_storage<sizeof(void *)>::type, const T>(&av->holder_.inline_buf));
291	      av_p->operate_ = av->operate_;
292	      break;
293	    }
294	    case OperateType::kOpMove: {
295	      auto *const av_p = PtrToPtr<void, AnyValue>(out);
296	      auto *const moved_t_p = const_cast<T *>(PtrToPtr<const ValueBuf, const T>(&av->holder_.inline_buf));
297	      (void)new (&av_p->holder_.inline_buf) T(std::move(*moved_t_p));
298	      av_p->operate_ = av->operate_;
299	      break;
300	    }
301	    case OperateType::kGetTypeId:
302	      *PtrToPtr<void, TypeId>(out) = GetTypeId<T>();
303	      break;
304	    default:
305	      break;
306	  }
307	}
308	
309	template <class T>
310	auto AnyValue::MutableGet() -> T * {
311	  if (!SameType<T>()) {
312	    return nullptr;
313	  }
314	  if (IsEmpty()) {
315	    return nullptr;
316	  }
317	  void *addr = nullptr;
318	  operate_(OperateType::kOpGetAddr, this, &addr);
319	  return PtrToPtr<void, T>(addr);
320	}
321	}  // namespace ge
322	
323	#endif  // EXECUTE_GRAPH_ANY_VALUE_H
